  "summary": {
   "en": "In Korea, tea and etiquette have long been one: the word for an ancestral rite, charye, literally means 'tea rite.' This article walks through the flow of everyday darye, from boiling the water to offering the cup with both hands.",
   "ja": "祭祀を「茶礼（チャレ）」と呼ぶことからも分かるように、韓国では茶と礼儀は古くから一体でした。水を沸かし茶罐を温め、両手で茶を差し上げる生活茶礼の流れを紹介します。",
   "ko": "차례(茶禮)라는 말에서 알 수 있듯, 한국에서 차는 예절과 한 몸이었습니다. 물을 끓여 다관을 데우고, 정성껏 우려 두 손으로 건네는 생활 다례의 흐름을 소개합니다.",
   "yue": "韓國人將祭祀叫做「茶禮」（차례），可見茶同禮儀自古已經密不可分。呢篇會介紹由煲水、溫壺到雙手奉茶嘅日常茶禮流程。",
   "zh-CN": "从祭祀被称为“茶礼”（차례）一词便可看出，在韩国，茶与礼仪自古密不可分。本文介绍从烧水、温壶到双手奉茶的日常茶礼流程。",
   "zh-TW": "從祭祀被稱為「茶禮」（차례）一詞便可看出，在韓國，茶與禮儀自古密不可分。本文介紹從燒水、溫壺到雙手奉茶的日常茶禮流程。",
   "hi": "कोरिया में चाय और शिष्टाचार लंबे समय से एक ही चीज़ रहे हैं: पूर्वजों के अनुष्ठान के लिए प्रयुक्त शब्द 'चार्ये' (차례) का शाब्दिक अर्थ ही 'चाय अनुष्ठान' है। यह लेख पानी उबालने से लेकर दोनों हाथों से कप पेश करने तक, रोज़मर्रा के दार्ये की पूरी प्रक्रिया को समझाता है।",
   "th": "ในเกาหลี ชากับมารยาทเป็นเรื่องเดียวกันมานานแล้ว คำว่า ชารเย ซึ่งหมายถึงพิธีไหว้บรรพบุรุษ แปลตรงตัวได้ว่า 'พิธีชา' บทความนี้จะพาไปรู้จักขั้นตอนของดาแรในชีวิตประจำวัน ตั้งแต่การต้มน้ำไปจนถึงการยื่นถ้วยชาด้วยสองมือ",
   "vi": "Ở Hàn Quốc, trà và lễ nghi từ lâu đã là một: từ chỉ nghi lễ cúng tổ tiên, charye, theo nghĩa đen có nghĩa là 'lễ trà'. Bài viết này giới thiệu trình tự của darye thường ngày, từ đun nước đến dâng chén trà bằng cả hai tay.",
   "ar": "في كوريا، كان الشاي والآداب شيئًا واحدًا منذ زمن طويل: فكلمة «تشارييه» التي تُطلق على طقس تكريم الأسلاف تعني حرفيًا «طقس الشاي». يأخذك هذا المقال عبر خطوات الدارييه اليومية، من غلي الماء إلى تقديم الكوب بكلتا اليدين.",
   "ind": "Di Korea, teh dan etiket sejak lama menyatu: kata untuk upacara leluhur, charye, secara harfiah berarti 'ritual teh.' Artikel ini menelusuri alur darye sehari-hari, dari mendidihkan air hingga menyuguhkan cangkir dengan kedua tangan.",
   "tur": "Kore'de çay ile görgü kuralları uzun zamandır iç içedir: atalar için düzenlenen törene verilen ad olan charye, kelime anlamıyla 'çay töreni' demektir. Bu yazı, suyu kaynatmaktan fincanı iki elle sunmaya kadar günlük darye'nin akışını adım adım anlatıyor.",
   "si": "කොරියාවේදී තේ සහ ආචාර ධර්ම දිගු කලක් එකක් වී තිබේ: මුතුන් මිත්තන්ට පුද පූජා කරන චාරිත්‍රයට කියන 'චාරියේ' යන වචනයේ තේරුම වචනානුසාරයෙන්ම 'තේ චාරිත්‍රය' යන්නයි. මෙම ලිපියෙන් ජලය උණු කිරීමේ සිට අත් දෙකෙන්ම කෝප්පය පිළිගැන්වීම දක්වා එදිනෙදා දාරියේ ක්‍රියාවලිය විස්තර කෙරේ.",
   "es": "En Corea, el té y la etiqueta han sido una sola cosa desde hace mucho tiempo: la palabra para un rito ancestral, charye, significa literalmente «rito del té». Este artículo recorre el flujo del darye cotidiano, desde hervir el agua hasta ofrecer la taza con ambas manos.",
   "fr": "En Corée, le thé et l'étiquette ne font depuis longtemps qu'un : le mot qui désigne un rite ancestral, charye, signifie littéralement « rite du thé ». Cet article vous guide dans le déroulement du darye quotidien, de l'eau que l'on fait bouillir à la tasse offerte à deux mains.",
   "ne": "कोरियामा चिया र शिष्टाचार लामो समयदेखि एउटै हुन्: पुर्खाको संस्कारलाई बुझाउने शब्द 'छार्ये' को शाब्दिक अर्थ नै 'चिया संस्कार' हो। यस लेखले पानी उमाल्नेदेखि दुवै हातले कप अर्पण गर्नेसम्म, दैनिक दार्येको प्रवाहलाई चिनाउँछ।",
   "ms": "Di Korea, teh dan adab telah lama menjadi satu: perkataan bagi upacara nenek moyang, charye, secara harfiah bermaksud 'upacara teh.' Artikel ini membawa anda melalui aliran darye harian, daripada mendidihkan air hinggalah mempersembahkan cawan dengan kedua-dua tangan.",
   "ru": "В Корее чай и этикет издавна были едины: слово, обозначающее обряд почитания предков, чарэ, буквально означает «чайный обряд». В этой статье рассказывается о порядке повседневного дарэ — от кипячения воды до подношения чашки обеими руками."
  },
