  "summary": {
   "en": "Born in Chaozhou and southern Fujian, gongfu tea brews strong tea in a tiny pot or gaiwan and shares it over many short infusions. Learn what the fairness pitcher and aroma cup do, and why 'gongfu' means time and care.",
   "ja": "潮州と閩南に始まる工夫茶は、小さな茶罐や蓋碗で濃く淹れ、何度にも分けて味わう方式です。公道杯と聞香杯の役割、「工夫」という名の意味を紹介します。",
   "ko": "조주와 민난에서 시작된 공부차는 작은 다관이나 개완으로 차를 진하게 우려 여러 번에 나눠 마시는 방식입니다. 공도배와 문향배의 역할, '공부'라는 이름의 뜻을 알아봅니다.",
   "yue": "源自潮州同閩南嘅工夫茶，用細壺或者蓋碗將茶沖得濃醇，分做好多次短泡慢慢品嚐。呢篇會介紹公道杯同聞香杯嘅作用，同埋「工夫」兩個字嘅意思。",
   "zh-CN": "源于潮州与闽南的工夫茶，用小壶或盖碗把茶泡得浓醇，分作多次短泡慢慢品饮。本文介绍公道杯与闻香杯的作用，以及“工夫”二字的含义。",
   "zh-TW": "源於潮州與閩南的工夫茶，用小壺或蓋碗把茶泡得濃醇，分作多次短泡慢慢品飲。本文介紹公道杯與聞香杯的作用，以及「工夫」二字的含義。",
   "hi": "चाओझोउ और दक्षिणी फ़ुजियान में जन्मी गोंगफ़ू चाय छोटी-सी केतली या गायवान में तेज़ चाय बनाती है और उसे कई छोटी-छोटी बारों में साझा करती है। जानिए कि न्याय पात्र और खुशबू कप क्या काम करते हैं, और 'गोंगफ़ू' का अर्थ समय और देखभाल क्यों है।",
   "th": "ชากงฟูถือกำเนิดที่เฉาโจวและฝูเจี้ยนตอนใต้ เป็นการชงชาเข้มข้นในกาใบเล็กหรือไก้หว่าน แล้วแบ่งกันดื่มหลายรอบ รอบละสั้น ๆ มาทำความรู้จักหน้าที่ของเหยือกแบ่งชาและถ้วยดมกลิ่น และเหตุผลที่คำว่า 'กงฟู' หมายถึงเวลาและความใส่ใจ",
   "vi": "Ra đời ở Triều Châu và miền nam Phúc Kiến, trà công phu pha trà đậm trong chiếc ấm nhỏ xíu hoặc gaiwan và chia sẻ qua nhiều lần pha ngắn. Hãy tìm hiểu chén công đạo và chén ngửi hương dùng để làm gì, và vì sao 'công phu' có nghĩa là thời gian và sự chăm chút.",
   "ar": "وُلد شاي غونغ فو في تشاوتشو وجنوب فوجيان، وهو يحضّر شايًا قويًا في إبريق صغير أو غايوان ويتشاركه عبر نقعات قصيرة كثيرة. تعرّف على ما يفعله إبريق العدالة وكوب الرائحة، ولماذا تعني كلمة «غونغ فو» الوقت والعناية.",
   "ind": "Lahir di Chaozhou dan Fujian selatan, teh gongfu menyeduh teh pekat dalam teko kecil atau gaiwan dan membaginya dalam banyak seduhan singkat. Pelajari fungsi teko keadilan dan cangkir aroma, serta mengapa 'gongfu' berarti waktu dan kepedulian.",
   "tur": "Chaozhou ve güney Fujian'da doğan gongfu çayı, minik bir demlikte ya da gaiwan'da koyu çay demler ve birçok kısa demleme boyunca paylaşır. Eşitlik sürahisi ile koku fincanının ne işe yaradığını ve 'gongfu'nun neden zaman ve özen anlamına geldiğini öğrenin.",
   "si": "චාඕජෝ සහ දකුණු ෆුජියන් ප්‍රදේශවල උපන් ගොංෆු තේ, කුඩා බඳුනක හෝ ගයිවානයක තද තේ පෙරා, කෙටි වාර බොහෝ ගණනක් පුරා බෙදා ගනියි. සාධාරණත්ව පිචරය සහ සුවඳ කෝප්පය කරන්නේ කුමක්ද, සහ 'ගොංෆු' යන්නෙන් අදහස් කරන්නේ කාලය සහ සැලකිල්ල ඇයි දැයි ඉගෙන ගන්න.",
   "es": "Nacido en Chaozhou y el sur de Fujian, el té gongfu prepara un té fuerte en una tetera diminuta o en un gaiwan y lo comparte en muchas infusiones cortas. Descubre qué hacen la jarra de la equidad y la taza de aroma, y por qué «gongfu» significa tiempo y dedicación.",
   "fr": "Né à Chaozhou et dans le sud du Fujian, le thé gongfu prépare un thé corsé dans une minuscule théière ou un gaiwan et se partage en de nombreuses infusions courtes. Découvrez le rôle du pichet d'équité et de la tasse à parfum, et pourquoi « gongfu » signifie temps et soin.",
   "ne": "छाओझोउ र दक्षिणी फुजियानमा जन्मिएको गोङफु चियाले सानो पात्र वा गाइवाङमा गाढा चिया बनाउँछ र धेरै छोटा भिजाइहरूमा बाँड्छ। फेयरनेस पिचर र अरोमा कपले के गर्छन् र 'गोङफु' भनेको किन समय र हेरचाह हो भनेर जान्नुहोस्।",
   "ms": "Lahir di Chaozhou dan selatan Fujian, teh gongfu membancuh teh pekat dalam teko kecil atau gaiwan dan berkongsinya melalui banyak resapan pendek. Ketahui fungsi jag keadilan dan cawan aroma, dan mengapa 'gongfu' bermaksud masa dan ketelitian.",
   "ru": "Родившийся в Чаочжоу и на юге Фуцзяни, чай гунфу заваривает крепкий чай в крошечном чайнике или гайвани и делится им за множество коротких проливов. Узнайте, для чего нужны чаша справедливости и ароматическая чашка, и почему «гунфу» означает время и заботу."
  },
