     "h": "Laoren cha, tea shared slowly",
     "p": "Laoren cha (老人茶, 'elders' tea') was the everyday custom of older people gathering under trees or eaves to brew oolong strong in a small pot and share it slowly. The word 'elders' carries an attitude: tea is never rushed."
