  "summary": {
   "en": "In Taiwan, elders once gathered to share strong oolong from tiny clay pots — a custom called laoren cha that grew into today's tea-art houses. Discover the aroma-first ritual using the scent cup.",
   "ja": "台湾では、小さな紫砂壺で烏龍茶を濃く淹れて分かち合う「老人茶」の文化が、茶芸館の文化へと受け継がれました。聞香杯でまず香りを楽しむ独特の順序を紹介します。",
   "ko": "대만에서는 우롱차를 작은 자사호로 진하게 우려 나눠 마시는 노인차 문화가 다예관 문화로 이어졌습니다. 문향배로 향을 먼저 맡는 독특한 순서를 소개합니다.",
   "yue": "喺台灣，用細紫砂壺將烏龍茶沖得濃醇、分住慢慢飲嘅「老人茶」文化，後來發展成茶藝館文化。呢篇會介紹先用聞香杯聞香嘅獨特次序。",
   "zh-CN": "在台湾，用小紫砂壶把乌龙茶泡得浓醇、分着慢慢喝的“老人茶”文化，后来发展成茶艺馆文化。本文介绍先用闻香杯闻香的独特顺序。",
   "zh-TW": "在台灣，用小紫砂壺把烏龍茶泡得濃醇、分著慢慢喝的「老人茶」文化，後來發展成茶藝館文化。本文介紹先用聞香杯聞香的獨特順序。",
   "hi": "ताइवान में बुज़ुर्ग कभी छोटी मिट्टी की केतलियों से तेज़ ऊलोंग साझा करने के लिए इकट्ठा होते थे — यह प्रथा 'लाओरेन चा' कहलाती थी और वही आज के चाय-कला घरों में विकसित हुई। खुशबू कप का उपयोग करके खुशबू को पहले रखने वाले इस अनुष्ठान को जानिए।",
   "th": "ในไต้หวัน ครั้งหนึ่งผู้สูงอายุเคยรวมตัวกันแบ่งปันชาอู่หลงเข้มข้นจากดินเผาใบเล็ก ธรรมเนียมที่เรียกว่า เหลาเหรินฉา ซึ่งเติบโตกลายมาเป็นร้านศิลปะชาในปัจจุบัน มาทำความรู้จักพิธีที่ให้ความสำคัญกับกลิ่นก่อนรส โดยใช้ถ้วยดมกลิ่นกัน",
   "vi": "Ở Đài Loan, các bậc cao niên từng tụ họp để chia sẻ trà ô long đậm từ những chiếc ấm đất nhỏ xíu — một phong tục gọi là laoren cha, sau này phát triển thành các trà nghệ quán ngày nay. Hãy khám phá nghi thức ưu tiên hương thơm bằng chén ngửi hương.",
   "ar": "في تايوان، كان كبار السن يجتمعون يومًا ليتشاركوا أولونغ قويًا من أباريق طينية صغيرة — عادة تسمى لاورين تشا نمت لتصبح بيوت فن الشاي اليوم. اكتشف طقس تقديم الرائحة أولًا باستخدام كوب العبير.",
   "ind": "Di Taiwan, para tetua dulu berkumpul untuk berbagi oolong pekat dari teko tanah liat kecil — kebiasaan yang disebut laoren cha yang tumbuh menjadi rumah seni teh masa kini. Temukan ritual mengutamakan aroma dengan cangkir penghirup aroma.",
   "tur": "Tayvan'da yaşlılar bir zamanlar minik toprak demliklerde koyu oolong paylaşmak için toplanırdı — laoren cha denen bu gelenek, günümüzün çay sanatı evlerine dönüştü. Koku fincanıyla önce kokuyu tatmaya dayanan ritüeli keşfedin.",
   "si": "තායිවානයේදී, වැඩිහිටියන් වරක් කුඩා මැටි බඳුන්වලින් තද ඌලොං බෙදා ගැනීමට රැස් වූහ — ලාඕරෙන් චා නම් සිරිත අද තේ-කලා නිවස බවට වර්ධනය විය. සුවඳ කෝප්පය භාවිතා කරමින් සුවඳට ප්‍රමුඛතාව දෙන චාරිත්‍රය සොයා ගන්න.",
   "es": "En Taiwán, los mayores solían reunirse para compartir un oolong fuerte en pequeñas teteras de arcilla, una costumbre llamada laoren cha que dio origen a las actuales casas del arte del té. Descubre el ritual de apreciar primero el aroma con la taza de aroma.",
   "fr": "À Taïwan, les anciens se réunissaient autrefois pour partager un oolong corsé préparé dans de minuscules théières en argile — une coutume appelée laoren cha, devenue les maisons d'art du thé d'aujourd'hui. Découvrez le rituel qui met l'arôme à l'honneur grâce à la tasse à parfum.",
   "ne": "ताइवानमा, वृद्धहरू एक समय साना माटाका पात्रहरूबाट गाढा उलोङ बाँड्न भेला हुन्थे — लाओरेन चा भनिने चलन, जुन आजका चिया-कला घरहरूमा विकास भयो। सुगन्ध कप प्रयोग गरेर सुगन्धलाई पहिले राख्ने विधि पत्ता लगाउनुहोस्।",
   "ms": "Di Taiwan, golongan tua dahulu berkumpul untuk berkongsi oolong pekat daripada teko tanah liat yang kecil — adat yang dipanggil laoren cha yang berkembang menjadi rumah seni teh hari ini. Temui ritual mengutamakan aroma menggunakan cawan haruman.",
   "ru": "На Тайване пожилые люди когда-то собирались, чтобы делиться крепким улуном из крошечных глиняных чайников — обычай под названием лаожэнь ча, который вырос в сегодняшние дома чайного искусства. Откройте для себя ритуал, где аромат на первом месте, с использованием ароматической чашки."
  },
