     "p": "コーヒーとミルクティーを混ぜた鴛鴦(ユンヨン)は、おしどりの名の通り二つが一杯に溶け合う、もう一つの看板ドリンクです。氷入りの紅茶にレモンを浮かべた凍檸茶(ドンレンチャー)も欠かせません。ストローでレモンを突いて果汁を出し、濃さを自分で調えるのが香港流の楽しみです。"
