     "h": "원앙과 동링차",
     "p": "커피와 밀크티를 섞은 원앙(鴛鴦)은 차찬탱을 대표하는 또 하나의 음료로, 이름처럼 두 가지가 한 잔에 어우러집니다. 얼음을 채운 홍차에 레몬 조각을 넣은 동링차(凍檸茶)도 빼놓을 수 없습니다. 빨대로 레몬을 콕콕 찔러 즙을 짜내며 농도를 조절하는 것이 홍콩식 재미입니다."
