     "p": "茶餐厅是香港随处可见的大众食堂。它由卖冰饮和简单西式小吃的冰室发展而来，第二次世界大战后，逐渐成为把西餐本地化、便宜又快速的餐厅。多士配奶茶开启早晨，炒面炒饭解决午餐，这里就是香港人日常生活的缩影。"
