     "p": "마살라 차이는 찻잎을 뜨거운 물에 우리는 방식이 아니라, 물과 우유에 홍차와 설탕, 향신료를 함께 넣고 냄비에서 끓여 만드는 것이 특징입니다. 끓이는 동안 향신료의 향과 홍차의 맛이 우유에 진하게 배어, 달고 진한 한 잔이 완성됩니다. 가정마다, 가게마다 향신료 배합이 조금씩 달라 그 집만의 맛이 있습니다."
