  "summary": {
   "en": "Water kept boiling in a samovar, strong zavarka concentrate diluted to taste — Russia's way of tea, with jam on the side, sugar cubes between the teeth, and the samovar as a companion of long train journeys.",
   "ja": "サモワールで湯を沸かし、濃縮茶「ザワルカ」を割って飲むロシアの方式。ジャムを添えたり、角砂糖を口に含んで飲んだりした昔の風習と、長旅の列車の伴侶を紹介します。",
   "ko": "사모바르로 물을 끓이고 농축차 자바르카를 희석해 마시는 러시아의 방식. 잼을 곁들이고 각설탕을 물고 마시던 옛 풍습, 그리고 기차 여행의 동반자를 소개합니다.",
   "yue": "用薩莫瓦爾煲水，將濃縮茶「扎瓦爾卡」溝稀嚟飲，呢個係俄羅斯嘅方式。仲有配果醬、含住方糖飲茶嘅老風俗，同埋長途火車上面嘅薩莫瓦爾。",
   "zh-CN": "用萨莫瓦尔烧水，把浓缩茶\"扎瓦尔卡\"稀释着喝，这是俄罗斯的方式。还有配果酱、把方糖含在嘴里喝茶的老风俗，以及长途火车上的萨莫瓦尔。",
   "zh-TW": "用薩莫瓦爾燒水，把濃縮茶「扎瓦爾卡」稀釋著喝，這是俄羅斯的方式。還有配果醬、把方糖含在嘴裡喝茶的老風俗，以及長途火車上的薩莫瓦爾。",
   "hi": "समोवार में उबलता रहता पानी, स्वाद के अनुसार पतला किया गया गाढ़ा ज़ावर्का काढ़ा — जैम के साथ, दाँतों के बीच चीनी का टुकड़ा रखकर, और लंबी रेल यात्राओं का साथी समोवार — यही है रूस की चाय शैली।",
   "th": "น้ำที่เดือดอยู่ตลอดในซาโมวาร์ ชาแก่เข้มข้นซาวาร์กาที่เจือจางตามชอบ — วิถีชาของรัสเซีย มีแยมเคียงข้าง ก้อนน้ำตาลคาบไว้ระหว่างฟัน และซาโมวาร์ที่เป็นเพื่อนคู่การเดินทางไกลด้วยรถไฟ",
   "vi": "Nước luôn sôi trong samovar, nước cốt trà đặc zavarka được pha loãng theo khẩu vị — cách uống trà của người Nga, với mứt ăn kèm, viên đường ngậm giữa hai hàm răng, và chiếc samovar đồng hành trên những chuyến tàu dài.",
   "ar": "ماء يبقى يغلي في ساموفار، ومركز زافاركا قوي يُخفف حسب الذوق — طريقة روسيا في الشاي، مع المربى على الجانب، ومكعبات سكر بين الأسنان، والساموفار رفيق رحلات القطارات الطويلة.",
   "ind": "Air yang terus mendidih dalam samovar, konsentrat zavarka pekat yang diencerkan sesuai selera — cara minum teh Rusia, dengan selai di samping, gula batu di antara gigi, dan samovar sebagai pendamping perjalanan kereta yang panjang.",
   "tur": "Semaverde kaynar halde tutulan su, damak zevkine göre seyreltilen koyu zavarka demi — yanında reçel, dişlerin arasında şeker küpleri ve uzun tren yolculuklarının yoldaşı semaverle Rusya'nın çay tarzı.",
   "si": "සමෝවාරයක ජලය නටමින් තබා ගෙන, තද zavarka සාන්ද්‍රණයක් රස අනුව තනුක කර බීම — ජෑම් පැත්තෙන් තබා ගෙන, සීනි කැට දත් අතර තබා ගෙන, සහ දිගු දුම්රිය ගමන්වල සහකාරියක් වූ සමෝවාරය සමඟ රුසියාවේ තේ බොන ආකාරය.",
   "es": "Agua siempre hirviendo en un samovar, un concentrado fuerte de zavarka que se diluye al gusto: así es el té en Rusia, con mermelada al lado, terrones de azúcar entre los dientes y el samovar como compañero de los largos viajes en tren.",
   "fr": "De l'eau maintenue bouillante dans un samovar, un concentré fort de zavarka dilué selon le goût — la façon russe de boire le thé, avec de la confiture à côté, des morceaux de sucre entre les dents, et le samovar comme compagnon des longs voyages en train.",
   "ne": "समोवारमा उम्लिरहेको पानी, स्वादअनुसार पातलो पारिने बाक्लो जाभार्का सान्द्र — रुसको चिया खाने तरिका, साथमा जाम, दाँतबीच चिनीको टुक्रा, र लामो रेल यात्राको साथी समोवार।",
   "ms": "Air yang sentiasa mendidih dalam samovar, pati teh zavarka yang pekat dicairkan mengikut citarasa — cara minum teh Rusia, dengan jem di sisi, ketulan gula di celah gigi, dan samovar sebagai teman perjalanan kereta api yang jauh.",
   "ru": "Вода, постоянно кипящая в самоваре, крепкий концентрат заварки, разбавленный по вкусу, — русский способ пить чай: с вареньем, с сахаром вприкуску и с самоваром как спутником долгих железнодорожных путешествий."
  },
