    {
     "h": "우리는 순서",
     "p": "먼저 뜨거운 물로 개완을 한 번 데운 뒤 물을 버리고 찻잎을 넣습니다. 물을 붓고 뚜껑을 덮어 잠시 우린 다음, 뚜껑으로 표면의 거품을 살짝 걷어 내면 준비가 끝납니다. 찻잎의 양은 차 종류마다 다르지만, 처음에는 개완 용량의 3분의 1쯤 넣는 것부터 시작해 보세요."
    },
    {
     "h": "따르는 법 — 뚜껑 틈이 핵심",
     "p": "뚜껑을 살짝 비스듬히 기울여 찻물이 빠져나갈 작은 틈을 만듭니다. 한 손의 엄지와 중지로 완의 양쪽 가장자리를 잡고, 검지로는 뚜껑 위를 가볍게 눌러 고정하세요. 그대로 손목을 기울이면 찻물만 따라지고 잎은 뚜껑에 걸려 남습니다. 틈이 너무 넓으면 잎이 함께 쏟아지니, 처음에는 좁게 여는 것이 요령입니다."
    },
    {
     "h": "뜨거울 때 대처법",
     "p": "개완이 뜨거워 잡기 힘들다면 대개 물을 너무 가득 채운 경우입니다. 물은 완의 8부쯤까지만 채우고, 그래도 뜨거우면 받침째 들어 올려 옮기세요. 입구가 밖으로 살짝 벌어진 개완은 손가락이 닿는 가장자리가 덜 뜨거워 입문용으로 좋습니다."
    },
    {
     "h": "초보자에게 좋은 이유",
     "p": "개완은 구조가 단순해 세척이 쉽고, 뚜껑을 열면 잎이 우러나는 모습을 직접 눈으로 볼 수 있습니다. 우림 시간을 자유롭게 조절할 수 있어 차마다 다른 최적의 맛을 찾기도 좋습니다. 가격 부담도 적어 첫 다구로 가장 많이 추천되는 이유입니다."
    }
