     "p": "基本原则是装进不透光的密封容器，放在阴凉干燥的地方。把茶分装进小容器，每次只取一小份，就不用频繁开合大罐，香气能保持得更久。厨房温湿度变化大、食物气味多，尽量把茶存放在其他房间的柜子里。"
