     "h": "冷藏保存的注意事项",
     "p": "绿茶和香气细腻的乌龙茶，只要密封可靠，冷藏可以更久地保持新鲜。但冷着的茶如果马上打开，空气中的水汽会凝结在茶叶上，所以取出后要先在常温放回温再开封。已经开封的茶不要在冷藏和常温之间来回移动，放在阴凉处尽快喝完更好。"
