     "p": "韓國從2023年起，食品日期標示由「流通期限」改為「消費期限」。流通期限指可以販售的期間，消費期限則指依照規定方法保存時可以安全食用的期間。茶葉是水分很少的乾燥食品，不會一過日期就變質，包裝上的日期與其說是安全界線，不如說更接近「風味保證期」。也就是說，日期不是決定丟不丟的分界線，而是告訴我們香氣和滋味最好的時期的指南。"
