     "p": "期限を過ぎたお茶でも、カビがなく変なにおいがしなければ、たいていは飲むことができます。ただ、時間がたった分だけ香りは薄くなり、味もぼんやりしがちです。逆に、葉にカビが見えたり、カビ臭い・湿ったにおいがしたりする場合は、日付にかかわらず捨ててください。一度湿気を吸ったお茶も、安全のため捨てるほうが安心です。淹れる前に乾いた葉のにおいを嗅ぎ、色を確認する習慣が役に立ちます。"
