  "summary": {
   "en": "The results are in for The Leafies 2026, the international tea awards run by the UK Tea Academy. The top honour went to a steamed green tea from Kagoshima, Japan, the black tea prize to a honey-scented black tea from Taiwan — and Taiwan swept 55 medals in all, including seven golds.",
   "ja": "英国のUK Tea Academyが主催する国際的なお茶の品評会「The Leafies 2026」の結果が発表されました。最高賞は日本の鹿児島の蒸し製緑茶に、紅茶部門の最高賞は台湾の蜜の香りの紅茶に贈られました。台湾は金メダル7個を含む合計55個のメダルを獲得しました。",
   "ko": "영국 UK Tea Academy가 여는 국제 차 품평회 The Leafies의 2026년 결과가 나왔습니다. 최고상은 일본 가고시마의 증제 녹차, 홍차 부문 최고상은 대만의 꿀향 홍차가 받았고, 대만은 금메달 7개를 포함해 55개 메달을 휩쓸었습니다.",
   "yue": "由英國 UK Tea Academy 主辦嘅國際茶葉評比 The Leafies 2026 結果已經出爐喇。最高榮譽頒咗畀日本鹿兒島嘅蒸青綠茶，紅茶類最高獎就由台灣一款帶蜜香嘅紅茶奪得——台灣一共攞咗 55 面獎牌，包括 7 面金牌。",
   "zh-CN": "由英国 UK Tea Academy 主办的国际茶评比 The Leafies 2026 结果已经揭晓。最高荣誉授予了日本鹿儿岛的蒸青绿茶，红茶类最高奖则由台湾一款带蜜香的红茶获得——台湾共收获 55 枚奖牌，其中包括 7 枚金牌。",
   "zh-TW": "由英國 UK Tea Academy 主辦的國際茶葉評比 The Leafies 2026 結果已經揭曉。最高榮譽頒給了日本鹿兒島的蒸青綠茶，紅茶類最高獎則由台灣一款帶蜜香的紅茶獲得——台灣共收穫 55 面獎牌，其中包括 7 面金牌。",
   "hi": "UK Tea Academy द्वारा आयोजित अंतरराष्ट्रीय चाय पुरस्कार The Leafies 2026 के परिणाम आ गए हैं। सबसे बड़ा सम्मान जापान के Kagoshima की भाप से तैयार हरी चाय को मिला, काली चाय का पुरस्कार Taiwan की शहद जैसी खुशबू वाली काली चाय को मिला — और Taiwan ने सात स्वर्ण सहित कुल 55 पदक अपने नाम किए।",
   "th": "ผลรางวัล The Leafies 2026 เวทีประกวดชานานาชาติที่จัดโดย UK Tea Academy ประกาศออกมาแล้ว รางวัลสูงสุดตกเป็นของชาเขียวนึ่งจาก Kagoshima ประเทศญี่ปุ่น รางวัลชาดำตกเป็นของชาดำกลิ่นน้ำผึ้งจาก Taiwan — และ Taiwan กวาดไปทั้งหมด 55 เหรียญ รวมถึง 7 เหรียญทอง",
   "vi": "Kết quả của The Leafies 2026, giải thưởng trà quốc tế do UK Tea Academy tổ chức, đã được công bố. Giải thưởng cao nhất thuộc về một loại trà xanh hấp từ Kagoshima, Nhật Bản, giải trà đen thuộc về một loại trà đen thơm mùi mật ong từ Taiwan — và Taiwan giành tổng cộng 55 huy chương, trong đó có bảy huy chương vàng.",
   "ar": "صدرت نتائج ذا ليفيز 2026، جوائز الشاي الدولية التي تديرها أكاديمية الشاي في المملكة المتحدة. ذهبت الجائزة الكبرى إلى شاي أخضر مبخر من كاغوشيما في اليابان، وجائزة الشاي الأسود إلى شاي أسود برائحة العسل من تايوان — وحصدت تايوان 55 ميدالية في المجموع، منها سبع ذهبيات.",
   "ind": "Hasil The Leafies 2026 telah diumumkan, penghargaan teh internasional yang diselenggarakan oleh UK Tea Academy. Penghargaan tertinggi diraih teh hijau kukus dari Kagoshima, Jepang, hadiah teh hitam diraih teh hitam beraroma madu dari Taiwan — dan Taiwan menyapu 55 medali seluruhnya, termasuk tujuh emas.",
   "tur": "UK Tea Academy tarafından düzenlenen uluslararası çay ödülleri The Leafies 2026'nın sonuçları açıklandı. En büyük onur, Japonya'nın Kagoshima kentinden buharda pişirilmiş bir yeşil çaya gitti; siyah çay ödülü, Tayvan'dan bal kokulu bir siyah çaya — ve Tayvan, yedisi altın olmak üzere toplam 55 madalya topladı.",
   "si": "UK Tea Academy විසින් පවත්වාගෙන යනු ලබන ජාත්‍යන්තර තේ සම්මාන වන The Leafies 2026 සඳහා ප්‍රතිඵල ප්‍රකාශයට පත් වී ඇත. ඉහළම ගෞරවය ජපානයේ කගෝෂිමා වල වාෂ්ප කළ කොළ තේ වර්ගයකට හිමි වූ අතර, කළු තේ ත්‍යාගය තායිවානයේ පැණි සුවඳැති කළු තේ වර්ගයකට හිමි විය — තවද රන් පදක්කම් හතක් ඇතුළුව, තායිවානය සමස්තයක් ලෙස පදක්කම් 55 ක් දිනා ගත්තේය.",
   "es": "Ya están los resultados de The Leafies 2026, los premios internacionales de té organizados por la UK Tea Academy. El máximo honor fue para un té verde al vapor de Kagoshima, Japón, el premio al té negro para un té negro con aroma a miel de Taiwán, y Taiwán arrasó con 55 medallas en total, incluidas siete de oro.",
   "fr": "Les résultats des Leafies 2026 sont tombés : ce concours international du thé est organisé par la UK Tea Academy. La plus haute distinction est allée à un thé vert étuvé de Kagoshima, au Japon, le prix du thé noir à un thé noir aux notes de miel de Taïwan — et Taïwan a raflé 55 médailles en tout, dont sept en or.",
   "ne": "UK Tea Academy ले सञ्चालन गर्ने अन्तर्राष्ट्रिय चिया पुरस्कार The Leafies 2026 को नतिजा आएको छ। शीर्ष सम्मान जापानको कागोशिमाको बाफमा बनाइएको हरियो चियालाई गयो, कालो चियाको पुरस्कार ताइवानको महको सुगन्ध भएको कालो चियालाई — र ताइवानले सात स्वर्णसहित कुल 55 पदक जित्यो।",
   "ms": "Keputusan telah diumumkan untuk The Leafies 2026, anugerah teh antarabangsa yang dikendalikan oleh UK Tea Academy. Penghormatan tertinggi dimenangi oleh teh hijau kukus dari Kagoshima, Jepun, hadiah teh hitam oleh teh hitam berperisa madu dari Taiwan — dan Taiwan menyapu 55 pingat kesemuanya, termasuk tujuh emas.",
   "ru": "Объявлены результаты The Leafies 2026, международной чайной премии, проводимой UK Tea Academy. Высшая награда досталась пропаренному зелёному чаю из Кагосимы, Япония, приз за чёрный чай — чёрному чаю с медовым ароматом с Тайваня, а Тайвань в общей сложности завоевал 55 медалей, включая семь золотых."
  },
